1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8	)
9	
10	// PlanChange is one record in a lineage adjustment plan: the dataset name and
11	// the complete list of its direct upstreams after the batch is applied.
12	//
13	// A change may name a dataset that does not exist yet (it is registered) or an
14	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
15	// mentioned in the plan keep their current direct upstreams.
16	type PlanChange struct {
17		Name      string   `json:"name"`
18		Upstreams []string `json:"upstreams"`
19	}
20	
21	// Plan is a batch of lineage adjustments read from a JSON file.
22	//
23	// Removals names datasets that must be absent from the final graph. Deleting a
24	// name that does not currently exist is a no-op (it is not reported as an
25	// actual removal), so a successful plan can be applied again with empty change
26	// and impact lists. A name listed in Removals must not also appear in Changes.
27	type Plan struct {
28		Changes  []PlanChange `json:"changes"`
29		Removals []string     `json:"removals"`
30	}
31	
32	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
33	// downstream dataset derives from the upstream dataset.
34	type Relation struct {
35		Upstream   string `json:"upstream"`
36		Downstream string `json:"downstream"`
37	}
38	
39	// GraphDataset is one dataset record in the on-disk graph JSON.
40	type GraphDataset struct {
41		Name      string   `json:"name"`
42		Upstreams []string `json:"upstreams"`
43	}
44	
45	// GraphFile is the on-disk JSON representation of a lineage graph.
46	type GraphFile struct {
47		Datasets []GraphDataset `json:"datasets"`
48	}
49	
50	// BatchReport is the deterministic report produced by preview and apply.
51	//
52	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
53	// lists are sorted by name byte order; relation lists are sorted by upstream
54	// then downstream.
55	type BatchReport struct {
56		FinalGraph          GraphFile  `json:"finalGraph"`
57		NewDatasets         []string   `json:"newDatasets"`
58		ChangedDatasets     []string   `json:"changedDatasets"`
59		RemovedDatasets     []string   `json:"removedDatasets"`
60		AddedRelations      []Relation `json:"addedRelations"`
61		RemovedRelations    []Relation `json:"removedRelations"`
62		AffectedDownstreams []string   `json:"affectedDownstreams"`
63	}
64	
65	// graphAdjacency derives the normalized parent map from the in-memory graph.
66	// It rejects nil lineage nodes, empty names, names that are not valid UTF-8
67	// (dataset names or direct upstream references), and references to upstreams
68	// that are not registered; the name/reference rules are the shared ones from
69	// normalizeDatasets and validateAdjacencyReferences, also used by the file and
70	// snapshot readers. It does not check for cycles; use validateAcyclic for that.
71	func graphAdjacency(graph map[string]*Lineage) (adjacency, error) {
72		if graph == nil {
73			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
74		}
75		// Check encoding before anything that would quote these names or turn them
76		// into JSON: a missing-upstream check must not label an unregistered,
77		// non-UTF-8 upstream as ErrNotFound when the name itself is unusable, and
78		// json.Marshal would silently rewrite an invalid byte into U+FFFD. The
79		// check is read-only and reports the offending raw bytes.
80		if err := validateInMemoryNamesUTF8(graph); err != nil {
81			return nil, err
82		}
83		records := make([]GraphDataset, 0, len(graph))
84		for name, entry := range graph {
85			if entry == nil {
86				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
87			}
88			if name == "" {
89				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
90			}
91			records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
92		}
93		adj, err := normalizeDatasets(records)
94		if err != nil {
95			return nil, err
96		}
97		if err := validateAdjacencyReferences(adj); err != nil {
98			return nil, err
99		}
100		return adj, nil
101	}
102	
103	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
104	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
105	// references), missing upstreams, and cycles. It does not mutate the graph.
106	//
107	// A graph that fails validation cannot be used as the basis for a batch: an
108	// adjustment plan must not be allowed to paper over pre-existing corruption.
109	func ValidateGraph(graph map[string]*Lineage) error {
110		adj, err := graphAdjacency(graph)
111		if err != nil {
112			return err
113		}
114		return validateAcyclic(adj)
115	}
116	
117	// computeBatch validates the graph and plan, then computes the final adjacency
118	// and the diff report. It does not mutate graph. The returned adjacency is the
119	// graph as it will be after the batch; callers that want to commit it should
120	// pass it to applyAdjacency.
121	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
122		if err := ValidateGraph(graph); err != nil {
123			return nil, nil, err
124		}
125		original, err := graphAdjacency(graph)
126		if err != nil {
127			return nil, nil, err
128		}
129	
130		// Validate the plan: empty names and duplicate declarations reject the
131		// whole batch, naming the dataset and the reason.
132		declarations := make(map[string]int, len(plan.Changes))
133		for _, change := range plan.Changes {
134			if change.Name == "" {
135				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
136			}
137			declarations[change.Name]++
138			if declarations[change.Name] > 1 {
139				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
140			}
141		}
142	
143		// Validate removals: empty names, duplicate names, and names also declared
144		// as changes all reject the whole batch with the name and reason.
145		removalDecls := make(map[string]int, len(plan.Removals))
146		for _, name := range plan.Removals {
147			if name == "" {
148				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
149			}
150			removalDecls[name]++
151			if removalDecls[name] > 1 {
152				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
153			}
154			if _, ok := declarations[name]; ok {
155				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
156			}
157		}
158	
159		// Build the final adjacency: start from the original parents, replace each
160		// planned dataset's parents with its normalized upstreams.
161		final := make(adjacency, len(original)+len(plan.Changes))
162		for name, parents := range original {
163			final[name] = append([]string(nil), parents...)
164		}
165		for name := range removalDecls {
166			delete(final, name)
167		}
168		var newNames []string
169		var changedNames []string
170		for _, change := range plan.Changes {
171			wanted := uniqueSorted(change.Upstreams)
172			old, existed := original[change.Name]
173			switch {
174			case !existed:
175				newNames = append(newNames, change.Name)
176			case !stringSliceEqual(old, wanted):
177				changedNames = append(changedNames, change.Name)
178			}
179			final[change.Name] = wanted
180		}
181		sort.Strings(newNames)
182		sort.Strings(changedNames)
183	
184		// Datasets actually removed: names in removals that existed in the
185		// original graph. Deleting a name that does not exist is a no-op and is
186		// not reported, so a successful plan can be applied again with empty lists.
187		var removedNames []string
188		for name := range removalDecls {
189			if _, existed := original[name]; existed {
190				removedNames = append(removedNames, name)
191			}
192		}
193		sort.Strings(removedNames)
194	
195		// Every upstream must resolve to a dataset that exists in the FINAL graph
196		// (new datasets may reference each other regardless of plan order; a
197		// retained dataset that still references a deleted name is rejected here,
198		// with both the referrer and the referenced name in the error). Iterate
199		// over sorted names so the reported pair is deterministic.
200		names := make([]string, 0, len(final))
201		for name := range final {
202			names = append(names, name)
203		}
204		sort.Strings(names)
205		for _, name := range names {
206			for _, parent := range final[name] {
207				if _, ok := final[parent]; !ok {
208					return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
209				}
210			}
211		}
212		// The final graph must be acyclic, judged after all replacements.
213		if err := validateAcyclic(final); err != nil {
214			return nil, nil, err
215		}
216	
217		added, removed := diffRelations(original, final)
218		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
219	
220		report := &BatchReport{
221			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
222			NewDatasets:         newNames,
223			ChangedDatasets:     changedNames,
224			RemovedDatasets:     removedNames,
225			AddedRelations:      added,
226			RemovedRelations:    removed,
227			AffectedDownstreams: affected,
228		}
229		// Guarantee non-nil slices so JSON encodes empty lists as [].
230		if report.NewDatasets == nil {
231			report.NewDatasets = []string{}
232		}
233		if report.ChangedDatasets == nil {
234			report.ChangedDatasets = []string{}
235		}
236		if report.RemovedDatasets == nil {
237			report.RemovedDatasets = []string{}
238		}
239		if report.AddedRelations == nil {
240			report.AddedRelations = []Relation{}
241		}
242		if report.RemovedRelations == nil {
243			report.RemovedRelations = []Relation{}
244		}
245		if report.AffectedDownstreams == nil {
246			report.AffectedDownstreams = []string{}
247		}
248		return report, final, nil
249	}
250	
251	// PreviewBatch validates the graph and plan and returns the report WITHOUT
252	// mutating graph. Preview and apply for the same graph and plan produce
253	// identical reports.
254	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
255		report, _, err := computeBatch(graph, plan)
256		return report, err
257	}
258	
259	// ApplyBatch validates the plan, applies it to graph, and returns the report.
260	// On rejection, graph is left completely unchanged.
261	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
262		report, final, err := computeBatch(graph, plan)
263		if err != nil {
264			return nil, err
265		}
266		applyAdjacency(graph, final)
267		return report, nil
268	}
269	
270	// applyAdjacency rewrites the in-memory graph to match the final adjacency:
271	// nodes absent from final are removed, parents are replaced, and children are
272	// rebuilt from the parent edges.
273	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
274		for name := range graph {
275			if _, ok := final[name]; !ok {
276				delete(graph, name)
277			}
278		}
279		for name, parents := range final {
280			entry := graph[name]
281			if entry == nil {
282				entry = &Lineage{}
283				graph[name] = entry
284			}
285			entry.Dataset = name
286			entry.Parents = append([]string(nil), parents...)
287			entry.Children = nil
288		}
289		for name, parents := range final {
290			for _, parent := range parents {
291				graph[parent].Children = append(graph[parent].Children, name)
292			}
293		}
294		for name := range graph {
295			graph[name].Children = uniqueSorted(graph[name].Children)
296		}
297	}
298	
299	// diffRelations returns the directed edges present in final but not original
300	// (added) and present in original but not final (removed). Both lists are
301	// sorted by upstream then downstream.
302	func diffRelations(original, final adjacency) (added, removed []Relation) {
303		origEdges := edgeSet(original)
304		finalEdges := edgeSet(final)
305		for e := range finalEdges {
306			if !origEdges[e] {
307				added = append(added, e)
308			}
309		}
310		for e := range origEdges {
311			if !finalEdges[e] {
312				removed = append(removed, e)
313			}
314		}
315		sortRelations(added)
316		sortRelations(removed)
317		return added, removed
318	}
319	
320	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
321	func edgeSet(adj adjacency) map[Relation]bool {
322		set := make(map[Relation]bool)
323		for downstream, parents := range adj {
324			for _, upstream := range parents {
325				set[Relation{Upstream: upstream, Downstream: downstream}] = true
326			}
327		}
328		return set
329	}
330	
331	// sortRelations sorts by upstream then downstream.
332	func sortRelations(rels []Relation) {
333		sort.Slice(rels, func(i, j int) bool {
334			if rels[i].Upstream != rels[j].Upstream {
335				return rels[i].Upstream < rels[j].Upstream
336			}
337			return rels[i].Downstream < rels[j].Downstream
338		})
339	}
340	
341	// affectedDownstreams computes the impact set: starting from the seed datasets
342	// (new, actually changed, or actually removed), follow downstream (children)
343	// edges in BOTH the original and the final graphs. Datasets that are
344	// themselves seeds are excluded from the output; every other reachable dataset
345	// is included once.
346	//
347	// Walking both graphs matters when relations are deleted: a dataset that was
348	// reachable downstream before the change (and thus loses a lineage path) is
349	// still affected even if the edge is gone in the final graph. Removed datasets
350	// are seeds too, so a downstream that lost its upstream node is counted.
351	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
352		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
353		for _, name := range newNames {
354			seeds[name] = true
355		}
356		for _, name := range changedNames {
357			seeds[name] = true
358		}
359		for _, name := range removedNames {
360			seeds[name] = true
361		}
362	
363		origChildren := invertAdjacency(original)
364		finalChildren := invertAdjacency(final)
365	
366		seen := make(map[string]bool)
367		queue := make([]string, 0, len(seeds))
368		for seed := range seeds {
369			queue = append(queue, seed)
370		}
371		for len(queue) > 0 {
372			node := queue[0]
373			queue = queue[1:]
374			for _, child := range origChildren[node] {
375				if !seen[child] {
376					seen[child] = true
377					queue = append(queue, child)
378				}
379			}
380			for _, child := range finalChildren[node] {
381				if !seen[child] {
382					seen[child] = true
383					queue = append(queue, child)
384				}
385			}
386		}
387	
388		out := make([]string, 0, len(seen))
389		for name := range seen {
390			if !seeds[name] {
391				out = append(out, name)
392			}
393		}
394		sort.Strings(out)
395		return out
396	}
397	
398	// invertAdjacency maps each dataset to the datasets that depend on it (its
399	// children), with each child list sorted by name.
400	func invertAdjacency(adj adjacency) map[string][]string {
401		children := make(map[string][]string, len(adj))
402		for name, parents := range adj {
403			for _, parent := range parents {
404				children[parent] = append(children[parent], name)
405			}
406		}
407		for name := range children {
408			sort.Strings(children[name])
409		}
410		return children
411	}
412	
413	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
414	// records with non-nil upstream lists.
415	func adjacencyToDatasets(adj adjacency) []GraphDataset {
416		names := make([]string, 0, len(adj))
417		for name := range adj {
418			names = append(names, name)
419		}
420		sort.Strings(names)
421		ds := make([]GraphDataset, 0, len(names))
422		for _, name := range names {
423			parents := adj[name]
424			if parents == nil {
425				parents = []string{}
426			}
427			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
428		}
429		return ds
430	}
431	
432	// stringSliceEqual reports whether a and b contain the same strings in the
433	// same order. Both are expected to be sorted and duplicate-free.
434	func stringSliceEqual(a, b []string) bool {
435		if len(a) != len(b) {
436			return false
437		}
438		for i := range a {
439			if a[i] != b[i] {
440				return false
441			}
442		}
443		return true
444	}
445	
446	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
447	// The graph must satisfy every structure rule a reader enforces; nil nodes,
448	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
449	// references), missing upstreams, and dependency cycles (including a dataset
450	// that lists itself) reject the export with no bytes returned, so a successful
451	// result can always be read back with UnmarshalGraphFile. The check is
452	// read-only: the in-memory graph is never modified.
453	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
454		adj, err := graphAdjacency(graph)
455		if err != nil {
456			return nil, err
457		}
458		if err := validateAcyclic(adj); err != nil {
459			return nil, err
460		}
461		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
462		return json.MarshalIndent(gf, "", "  ")
463	}
464	
465	// UnmarshalGraphFile parses the on-disk graph JSON and rebuilds the in-memory
466	// graph (parents and derived children). The graph is checked with the same
467	// structural rules a snapshot enforces (empty names, duplicate datasets,
468	// missing upstreams, and cycles); a structurally invalid graph is rejected so
469	// it cannot be used as the basis for a batch. As in a snapshot, a known field
470	// declared twice within the same object — datasets in the graph object, name
471	// or upstreams in a dataset record — is ambiguous and rejects the whole file,
472	// even when the duplicates carry identical values.
473	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
474		if err := checkGraphFileDuplicateFields(data); err != nil {
475			return nil, err
476		}
477		var gf GraphFile
478		if err := json.Unmarshal(data, &gf); err != nil {
479			return nil, fmt.Errorf("invalid graph JSON: %w", err)
480		}
481		adj, err := validateGraphStructureFromFile(gf.Datasets)
482		if err != nil {
483			return nil, err
484		}
485		// Rebuild children from the parent edges so the in-memory graph is
486		// consistent regardless of how the file was produced.
487		return lineageFromAdjacency(adj), nil
488	}
489	
490	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
491	// duplicate declarations) is validated later by computeBatch so that preview
492	// and apply share identical rejection behavior.
493	//
494	// A known field declared twice within the same object — changes or removals
495	// at the top level, name or upstreams inside one change record — is
496	// ambiguous: the reader would silently keep only the last declaration and
497	// drop the earlier adjustment. The whole plan is refused instead, even when
498	// the duplicates carry identical values, one is null, or the surviving value
499	// is a legal empty list. Field names are recognized the same way the decoder
500	// resolves them (after JSON unescaping, with Unicode case folding), so a
501	// second declaration spelled "Changes" or "changes" still collides;
502	// dataset names themselves stay case-sensitive. Unknown fields keep their
503	// ignore-everything behavior and may repeat freely.
504	func UnmarshalPlan(data []byte) (Plan, error) {
505		var p Plan
506		if err := checkPlanDuplicateFields(data); err != nil {
507			return p, err
508		}
509		if err := json.Unmarshal(data, &p); err != nil {
510			return p, fmt.Errorf("invalid plan JSON: %w", err)
511		}
512		return p, nil
513	}
514	
515	// checkGraphFileDuplicateFields applies the shared repeated-known-field rule
516	// (see duplicate_fields.go) to a standalone graph file, supplying the graph
517	// file's own location: datasets may be declared only once in the top-level
518	// graph object, and name and upstreams only once in each dataset record. The
519	// scan is the same checkGraphObject ParseSnapshot runs on the embedded graph,
520	// so preview, apply, and snapshot can never disagree about a graph that
521	// repeats a known field.
522	func checkGraphFileDuplicateFields(data []byte) error {
523		return runFieldScan(data, func(dec *json.Decoder) error {
524			return checkGraphObject(dec, "at the top level of the graph")
525		})
526	}
527	
528	// checkPlanDuplicateFields applies the shared repeated-known-field rule (see
529	// duplicate_fields.go) to a plan, supplying the plan's own field scope and
530	// locations: changes or removals at the top level, and name or upstreams
531	// inside each change record. A change record carries the same fields as a
532	// dataset record, so both use the shared datasetRecordFields scope and a plan
533	// can never be judged differently from the other documents about what counts
534	// as a repeated field.
535	func checkPlanDuplicateFields(data []byte) error {
536		return runFieldScan(data, func(dec *json.Decoder) error {
537			return checkObjectFields(dec, "at the top level of the plan", []knownField{
538				{name: "changes", nested: func(dec *json.Decoder) error {
539					return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
540						return checkObjectFields(dec, fmt.Sprintf("in the change record at index %d of \"changes\"", index), datasetRecordFields)
541					})
542				}},
543				{name: "removals"},
544			})
545		})
546	}
547

