1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file is the single implementation of the repeated-known-field rule
4	// shared by every JSON document the readers understand (snapshot, standalone
5	// graph file, and adjustment plan): within one object, a field the reader
6	// recognizes may be declared only once. A repeated declaration is ambiguous —
7	// the regular decoder would silently keep only the last value — so the whole
8	// document is refused, even when the duplicates carry identical values, the
9	// first is null, or the surviving value would pass every other check. Unknown
10	// fields keep their ignore-everything behavior and may repeat freely.
11	//
12	// Each document supplies only its own field scope (which keys are known at
13	// each level, and which known field's value nests another checked object or
14	// array) and its own error locations; the walking, matching, and error
15	// formatting below are common, so the three readers can never drift apart
16	// about what counts as a duplicate.
17	//
18	// Matching rules, common to every document:
19	//
20	//   - Field names are compared after JSON string unescaping and with the same
21	//     Unicode simple case-folding the decoder applies to its case-insensitive
22	//     field lookup (strings.EqualFold), so "name" and "Name" collide, and so
23	//     do spellings that only differ in a fold-equivalent rune such as
24	//     "dataſets" (long s) and "datasets". Dataset names themselves stay
25	//     case-sensitive; this folding applies to field names only.
26	//   - The decoder uses UseNumber so numbers are kept verbatim instead of being
27	//     converted to float64: a perfectly legal JSON number outside the float64
28	//     range (such as 1e400), even one buried in an ignored unknown field's
29	//     value, must not make the decoder error out and abort the scan —
30	//     otherwise an unrelated large number placed before a repeated known
31	//     field would hide that duplication. Malformed number syntax still fails
32	//     and is left to the regular parse to report.
33	//   - A document too malformed to keep walking aborts the scan; the regular
34	//     parse then reports the syntax or type error instead, so this check
35	//     never changes how invalid JSON fails.
36	package chainledger
37	
38	import (
39		"bytes"
40		"encoding/json"
41		"errors"
42		"fmt"
43		"strings"
44	)
45	
46	// errAbortScan stops the duplicate-field scan when the document is too
47	// malformed to keep walking; the regular parse then reports the syntax or
48	// type error instead.
49	var errAbortScan = errors.New("chainledger: abort duplicate field scan")
50	
51	// runFieldScan runs check over data with the scan decoder (UseNumber, so an
52	// oversized-but-legal number anywhere in the document cannot abort the walk).
53	// An aborted scan is not an error: the document is left to the regular parse,
54	// which reports the structural problem.
55	func runFieldScan(data []byte, check func(dec *json.Decoder) error) error {
56		dec := json.NewDecoder(bytes.NewReader(data))
57		dec.UseNumber()
58		if err := check(dec); err != nil && !errors.Is(err, errAbortScan) {
59			return err
60		}
61		return nil
62	}
63	
64	// knownField is one field an object reader recognizes: name is the canonical
65	// spelling reported in duplicate errors (matching is case-folded, so any
66	// equivalent spelling selects it), and nested, when non-nil, checks the
67	// field's value as another checked object or array. A known field without a
68	// nested check has its value skipped like any unknown field's.
69	type knownField struct {
70		name   string
71		nested func(dec *json.Decoder) error
72	}
73	
74	// matchKnownField returns the known field key selects, matching the decoder's
75	// case-insensitive field lookup, or nil if key is unknown.
76	func matchKnownField(key string, fields []knownField) *knownField {
77		for i := range fields {
78			if strings.EqualFold(key, fields[i].name) {
79				return &fields[i]
80			}
81		}
82		return nil
83	}
84	
85	// checkObjectFields scans the object the decoder is positioned at: each known
86	// field may be declared at most once, known fields with a nested check descend
87	// into their value, and every other value is skipped. location describes the
88	// object itself in duplicate errors. A value that is not an object is consumed
89	// and left for the regular parse to report.
90	func checkObjectFields(dec *json.Decoder, location string, fields []knownField) error {
91		tok, err := scanToken(dec)
92		if err != nil {
93			return err
94		}
95		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
96			return skipRest(dec, tok) // not an object: the regular parse reports it
97		}
98		seen := make(map[string]bool, len(fields))
99		for dec.More() {
100			key, err := scanKey(dec)
101			if err != nil {
102				return err
103			}
104			if field := matchKnownField(key, fields); field != nil {
105				if seen[field.name] {
106					return duplicateFieldError(field.name, location)
107				}
108				seen[field.name] = true
109				if field.nested != nil {
110					if err := field.nested(dec); err != nil {
111						return err
112					}
113					continue
114				}
115			}
116			if err := skipValue(dec); err != nil {
117				return err
118			}
119		}
120		_, err = scanToken(dec) // closing '}'
121		return err
122	}
123	
124	// checkArrayElements scans the array the decoder is positioned at, running
125	// check on every element with its zero-based index. A value that is not an
126	// array is consumed and left for the regular parse to report.
127	func checkArrayElements(dec *json.Decoder, check func(dec *json.Decoder, index int) error) error {
128		tok, err := scanToken(dec)
129		if err != nil {
130			return err
131		}
132		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
133			return skipRest(dec, tok) // not an array: the regular parse reports it
134		}
135		for index := 0; dec.More(); index++ {
136			if err := check(dec, index); err != nil {
137				return err
138			}
139		}
140		_, err = scanToken(dec) // closing ']'
141		return err
142	}
143	
144	// datasetRecordFields is the field scope of one dataset record — the same
145	// shape whether the record sits in a graph's "datasets" array or in a plan's
146	// "changes" array — so both readers judge one record identically.
147	var datasetRecordFields = []knownField{{name: "name"}, {name: "upstreams"}}
148	
149	// checkGraphObject scans one graph object wherever it appears (the top level
150	// of a standalone graph file, or the "graph" value inside a snapshot):
151	// datasets may be declared only once, and each record of the datasets array
152	// is checked for repeated name/upstreams declarations. location names the
153	// graph object itself in the duplicate error.
154	func checkGraphObject(dec *json.Decoder, location string) error {
155		return checkObjectFields(dec, location, []knownField{
156			{name: "datasets", nested: func(dec *json.Decoder) error {
157				return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
158					return checkObjectFields(dec, fmt.Sprintf("in the dataset record at index %d of \"datasets\"", index), datasetRecordFields)
159				})
160			}},
161		})
162	}
163	
164	// duplicateFieldError reports a known field declared twice, naming the field
165	// and where in the document the repetition occurred.
166	func duplicateFieldError(field, location string) error {
167		return fmt.Errorf("%w: field %q is declared more than once %s", ErrInvalidArgument, field, location)
168	}
169	
170	// scanToken reads one token; any decode failure aborts the scan so the
171	// regular parse can report the malformed document.
172	func scanToken(dec *json.Decoder) (json.Token, error) {
173		tok, err := dec.Token()
174		if err != nil {
175			return nil, errAbortScan
176		}
177		return tok, nil
178	}
179	
180	// scanKey reads the next key of the object currently being walked.
181	func scanKey(dec *json.Decoder) (string, error) {
182		tok, err := scanToken(dec)
183		if err != nil {
184			return "", err
185		}
186		key, ok := tok.(string)
187		if !ok {
