40	// validateInMemoryNamesUTF8 rejects an in-memory graph whose dataset name or
41	// direct upstream reference is not valid UTF-8.
42	//
43	// Such names cannot exist in a file read by the JSON readers (json.Unmarshal
44	// replaces invalid bytes with U+FFFD), but they can exist in a graph built
45	// through Register or by hand. They must never reach an exporter: encoding/json
46	// would silently replace every invalid byte with U+FFFD, so two different
47	// names ("p\xff" and "p\xfe") could serialize identically and a re-read graph
48	// would no longer be a faithful copy. The whole graph is rejected instead.
49	//
50	// Nodes are visited in name byte order and each node's parents in their stored
51	// order, so the first reported name is stable regardless of map iteration.
52	// The offending name is quoted with %q, which keeps the raw bytes readable
53	// ("p\xff" differs from "p\xfe", and a genuinely valid "p�" is shown as
54	// the replacement character itself). The graph is only read, never modified.
55	// Nil lineage nodes are skipped here; the caller rejects those separately.
56	func validateInMemoryNamesUTF8(graph map[string]*Lineage) error {
57		names := make([]string, 0, len(graph))
58		for name := range graph {
59			names = append(names, name)
60		}
61		sort.Strings(names)
62		for _, name := range names {
63			if !utf8.ValidString(name) {
64				return fmt.Errorf("%w: dataset name %q is not valid UTF-8, so the graph cannot be exported faithfully", ErrInvalidArgument, name)
65			}
66			entry := graph[name]
67			if entry == nil {
68				continue
69			}
70			for _, parent := range entry.Parents {
71				if !utf8.ValidString(parent) {
72					return fmt.Errorf("%w: dataset %q references upstream %q whose name is not valid UTF-8", ErrInvalidArgument, name, parent)
73				}
74			}
75		}
76		return nil
77	}
