119	// file readers: it normalizes the records, rejects empty names, duplicate
120	// datasets, and unregistered upstreams, then rejects cycles. The returned
121	// adjacency is the canonical form of the graph's semantics.
122	func validateGraphStructureFromFile(datasets []GraphDataset) (adjacency, error) {
123		adj, err := normalizeDatasets(datasets)
124		if err != nil {
