// validatePlanNameString inspects the raw bytes of one JSON string literal
// (quotes included) ...
func validatePlanNameString(raw []byte, location string) error {
    end := len(raw) - 1 // closing quote
    for i := 1; i < end; {
        c := raw[i]
        if c == '\\' {
            esc := raw[i+1]
            if esc != 'u' {
                i += 2
                continue
            }
            cp, err := hex4(raw[i+2 : i+6])
            if err != nil { return errAbortScan }  // can't happen post-parse
            i += 6
            if isHighSurrogate(cp) {
                // must be immediately followed by \uDC00–\uDFFF
                if i+6 <= end && raw[i] == '\\' && raw[i+1] == 'u' {
                    cp2, err := hex4(raw[i+2 : i+6])
                    if err == nil && isLowSurrogate(cp2) {
                        i += 6
                        continue
