        if c < utf8.RuneSelf {
            i++
            continue
        }
        r, size := utf8.DecodeRune(raw[i:end])
        if r == utf8.RuneError && size == 1 {
            return invalidBytesError(location)
        }
        i += size
    }
    return nil
}
