func validateNameStringLiteral(raw []byte, location string) error {
    end := len(raw) - 1 // index of the closing quote
    for i := 1; i < end; {
        c := raw[i]
        switch {
        case c == '\\':
            if i+1 >= end {
                return errAbortScan // truncated escape: the regular parse reports it
            }
