func hex4(b []byte) (rune, bool) {
    var v rune
    for _, c := range b {
        v <<= 4
        switch {
        case c >= '0' && c <= '9':
            v |= rune(c - '0')
        case c >= 'a' && c <= 'f':
            v |= rune(c-'a') + 10
        case c >= 'A' && c <= 'F':
            v |= rune(c-'A') + 10
        default:
            return 0, false
        }
    }
    return v, true
}
