// correctly paired surrogate escapes, and names that merely look like
// escapes (a backslash before an ordinary letter) stay legal; unknown
// fields and their nested strings are not checked. See
// plan_name_encoding.go.
func UnmarshalPlan(data []byte) (Plan, error) {
	var p Plan
