203	func hex4(b []byte) (rune, bool) {
204		var v rune
205		for _, c := range b {
206			v <<= 4
207			switch {
208			case c >= '0' && c <= '9':
209				v |= rune(c - '0')
210			case c >= 'a' && c <= 'f':
211				v |= rune(c-'a') + 10
212			case c >= 'A' && c <= 'F':
